class Solution:
    def canJump(self, nums: List[int]) -> bool:
        far = 0                             # 目前能到的最远下标
        for i, x in enumerate(nums):
            if i > far:                     # 连 i 都到不了
                return False
            far = max(far, i + x)
            if far >= len(nums) - 1:
                return True
        return True

