class Solution {
    public boolean canJump(int[] nums) {
        int far = 0;                                // 目前能到的最远下标
        for (int i = 0; i < nums.length; i++) {
            if (i > far) {                          // 连 i 都到不了
                return false;
            }
            far = Math.max(far, i + nums[i]);
            if (far >= nums.length - 1) {
                return true;
            }
        }
        return true;
    }
}

